package org.apache.commons.lang;

import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class Entities_addEntities_TriageGen2Test {

    private Entities entities;

    @Before
    public void setUp() {
        // Since we are testing addEntities which calls addEntity, 
        // and addEntity is part of the same class, we use a spy to verify internal calls.
        entities = spy(new Entities());
    }

    @Test
    public void testAddEntities_Success() {
        String[][] input = {
            {"EntityA", "10"},
            {"EntityB", "20"},
            {"EntityC", "30"}
        };

        entities.addEntities(input);

        // Verify that addEntity was called for each element in the array
        verify(entities).addEntity("EntityA", 10);
        verify(entities).addEntity("EntityB", 20);
        verify(entities).addEntity("EntityC", 30);
    }

    @Test
    public void testAddEntities_EmptyArray() {
        String[][] input = {};

        entities.addEntities(input);

        // Verify no interactions with addEntity when array is empty
        verify(entities, never()).addEntity(anyString(), anyInt());
    }

    @Test(expected = NumberFormatException.class)
    public void testAddEntities_InvalidIntegerFormat() {
        String[][] input = {
            {"EntityA", "not_a_number"}
        };

        // This should throw NumberFormatException due to Integer.parseInt
        entities.addEntities(input);
    }

    @Test(expected = ArrayIndexOutOfBoundsException.class)
    public void testAddEntities_MalformedInnerArray() {
        // Array where the inner array doesn't have index 1
        String[][] input = {
            {"EntityA"}
        };

        entities.addEntities(input);
    }

    @Test(expected = NullPointerException.class)
    public void testAddEntities_NullInput() {
        // Testing null input to check behavior (will throw NPE on entityArray.length)
        entities.addEntities(null);
    }

    @Test(expected = NullPointerException.class)
    public void testAddEntities_NullInnerArray() {
        // Testing array containing a null element
        String[][] input = {
            null
        };

        entities.addEntities(input);
    }
}
